/** An assignee must be an active member of this workspace. Anyone else is not found. */
async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId | null,
): Promise<void> {
  if (userId === null) return;
  const member = await memberRepo.findMember(orgId, userId);
  if (member === null || member.status !== "active") {
    throw new NotFoundError("Member", userId);
  }
}

/**
 * A parent must be a live issue in the same project. A parent that lives in
 * another workspace is a tenant-scope violation; every other mismatch is not
 * found, and nothing is written.
 */
async function assertParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId | null,
): Promise<void> {
  if (parentId === null) return;
  const parent = await issueRepo.findIssueByIdAnyOrg(parentId);
  if (parent === null) throw new NotFoundError("Issue", parentId);
  if (parent.orgId !== orgId) assertOrgScope(actor, parent.orgId);
  if (parent.archivedAt !== null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** Every label id must be one of this workspace's own labels. */
async function assertWorkspaceLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;
  const found = await labelRepo.findLabelsByIds(labelIds);
  const byId = new Map(found.map((label) => [label.id, label]));
  for (const labelId of labelIds) {
    const label = byId.get(labelId);
    if (label === undefined) throw new NotFoundError("Label", labelId);
    if (label.orgId !== orgId) assertOrgScope(actor, label.orgId);
  }
}

